create extension if not exists "pgcrypto";
create type public.app_role as enum ('superadmin', 'admin', 'client');
create type public.expense_status as enum ('draft', 'submitted', 'under_review', 'observed', 'approved', 'rejected');
create type public.document_status as enum ('pending', 'uploaded', 'approved', 'observed', 'rejected');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role public.app_role not null default 'client', created_at timestamptz not null default now());
create table public.companies (id uuid primary key default gen_random_uuid(), name text not null, tax_id text unique, active boolean not null default true, created_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete restrict, name text not null, code text not null unique, active boolean not null default true, created_at timestamptz not null default now());
create table public.project_members (project_id uuid references public.projects(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, role public.app_role not null default 'client', primary key (project_id, user_id));
create table public.budget_categories (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, name text not null, position integer not null default 0, unique (project_id, name));
create table public.budget_items (id uuid primary key default gen_random_uuid(), category_id uuid not null references public.budget_categories(id) on delete cascade, name text not null, allocated_amount numeric(14,2) not null check (allocated_amount >= 0), position integer not null default 0);
create table public.document_requirements (id uuid primary key default gen_random_uuid(), budget_item_id uuid not null references public.budget_items(id) on delete cascade, name text not null, required boolean not null default true, requires_validity_period boolean not null default false, accepted_mime_types text[] not null default array['application/pdf','image/jpeg','image/png'], unique (budget_item_id, name));
create table public.expenses (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id), budget_item_id uuid not null references public.budget_items(id), submitted_by uuid not null references public.profiles(id), description text not null, amount numeric(14,2) not null check (amount > 0), expense_date date not null, status public.expense_status not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.expense_documents (id uuid primary key default gen_random_uuid(), expense_id uuid not null references public.expenses(id) on delete cascade, requirement_id uuid references public.document_requirements(id) on delete set null, storage_provider text not null default 'r2' check (storage_provider = 'r2'), storage_key text not null unique, original_name text not null, mime_type text not null, byte_size bigint not null check (byte_size > 0), validity_start date, validity_end date, status public.document_status not null default 'uploaded', uploaded_at timestamptz not null default now());
create table public.document_reviews (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.expense_documents(id) on delete cascade, reviewer_id uuid not null references public.profiles(id), status public.document_status not null, comment text, created_at timestamptz not null default now());

alter table public.profiles enable row level security; alter table public.companies enable row level security; alter table public.projects enable row level security; alter table public.project_members enable row level security; alter table public.budget_categories enable row level security; alter table public.budget_items enable row level security; alter table public.document_requirements enable row level security; alter table public.expenses enable row level security; alter table public.expense_documents enable row level security; alter table public.document_reviews enable row level security;
create function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select coalesce((select role in ('superadmin','admin') from public.profiles where id = auth.uid()), false) $$;
create function public.is_project_member(target uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.project_members where project_id = target and user_id = auth.uid()) $$;
create policy "admin companies" on public.companies for all using (public.is_admin()) with check (public.is_admin());
create policy "read projects" on public.projects for select using (public.is_admin() or public.is_project_member(id)); create policy "admin projects" on public.projects for all using (public.is_admin()) with check (public.is_admin());
create policy "admin memberships" on public.project_members for all using (public.is_admin()) with check (public.is_admin()); create policy "admin categories" on public.budget_categories for all using (public.is_admin()) with check (public.is_admin()); create policy "admin items" on public.budget_items for all using (public.is_admin()) with check (public.is_admin()); create policy "admin requirements" on public.document_requirements for all using (public.is_admin()) with check (public.is_admin());
create policy "read expenses" on public.expenses for select using (public.is_admin() or public.is_project_member(project_id)); create policy "client create expenses" on public.expenses for insert with check (submitted_by = auth.uid() and public.is_project_member(project_id)); create policy "client update draft expenses" on public.expenses for update using (submitted_by = auth.uid() and status in ('draft','observed'));
create policy "read documents" on public.expense_documents for select using (exists (select 1 from public.expenses e where e.id = expense_id and (public.is_admin() or public.is_project_member(e.project_id)))); create policy "add own documents" on public.expense_documents for insert with check (exists (select 1 from public.expenses e where e.id = expense_id and e.submitted_by = auth.uid())); create policy "admin reviews" on public.document_reviews for all using (public.is_admin()) with check (public.is_admin());
